'use strict';
const planOptions=(chosen)=>Object.values(RijaaPlans.plans).map(p=>`<option value="${p.id}" ${p.id===chosen?'selected':''}>${p.name} · ${p.price} ريال · ${p.cards} بطاقة</option>`).join('');
let requestedPlan='basic';
whatsapp=function(){const a=account(),p=RijaaPlans.plans[requestedPlan]||RijaaPlans.forAccount(a);const message=`مرحبًا، أرغب في باقة رجعة ${p.name} بسعر ${p.price} ريال شهريًا، ${p.cards} تصميم بطاقة ولاء و${p.employees} موظف، وعملاء غير محدودين.${a?`\nمعرّف الحساب: ${a.id}\nالنشاط: ${db.shops.find(s=>s.id===a.shop)?.name}`:''}`;location.assign(`https://wa.me/${db.settings.whatsapp}?text=${encodeURIComponent(message)}`);};
const planHome=homeHTML;
homeHTML=function(){const box=document.createElement('div');box.innerHTML=planHome();box.querySelector('.pricing').innerHTML=`<div class="pricing-copy"><div class="eyebrow">ثلاث باقات تناسب نشاطك</div><h2>ابدأ ببطاقة، وكبّر برنامجك.</h2><p>العدد يخص تصاميم برامج الولاء. بطاقات العملاء غير محدودة في جميع الباقات.</p></div><div class="plans-grid">${Object.values(RijaaPlans.plans).map(p=>`<article class="price-card"><span class="pill">${p.name}</span><div class="price">${p.price}<span> ريال / شهر</span></div><div class="feature-list"><div>${icon('check')} ${p.cards} ${p.cards===1?'تصميم بطاقة ولاء':'تصاميم بطاقات ولاء'}</div><div>${icon('check')} ${p.employees} ${p.employees===1?'حساب موظف':'حسابات موظفين'}</div><div>${icon('check')} عملاء غير محدودين</div><div>${icon('check')} برامج زيارات وخصومات ونقاط</div><div>${icon('check')} تخصيص الألوان والشعار والخلفية</div><div>${icon('check')} إدارة العملاء وسجل العمليات</div></div><button class="btn lime full" data-action="choose-plan" data-plan="${p.id}">اشترك عبر واتساب</button><small>الدفع والتفعيل عبر الإدارة. السعر السنوي بالتفاوض.</small></article>`).join('')}</div>`;return box.innerHTML;};
const oldAccountRows=accountRows;
accountRows=function(accounts){const box=document.createElement('tbody');box.innerHTML=oldAccountRows(accounts);accounts.forEach(a=>{const btn=Array.from(box.querySelectorAll('[data-action=activate-user]')).find(b=>b.dataset.id===a.id);if(btn){const field=document.createElement('label');field.className='field';field.innerHTML=`<span>باقة الاشتراك</span><select data-plan-account="${esc(a.id)}" aria-label="باقة ${esc(a.name)}">${planOptions(RijaaPlans.forAccount(a).id)}</select>`;btn.closest('td').prepend(field);}});return box.innerHTML;};
const planSubscription=subscriptionHTML;
subscriptionHTML=function(){const a=shopAccount(),p=RijaaPlans.forAccount(a),box=document.createElement('div');box.innerHTML=planSubscription();box.querySelectorAll('.page-head p,.page-head .eyebrow').forEach(e=>{if(/١٩٩|غير محدودة/.test(e.textContent))e.textContent=`باقة ${p.name} · ${p.price} ريال شهريًا`;});const details=box.querySelector('.subscription-details');if(details){details.lastElementChild.innerHTML=`<span>تصاميم البطاقات</span><b>${p.cards}</b>`;details.insertAdjacentHTML('beforeend',`<div><span>الباقة</span><b>${p.name} · ${p.price} ريال / شهر</b></div><div><span>حسابات الموظفين</span><b>${p.employees}</b></div><div><span>بطاقات العملاء</span><b>غير محدودة</b></div>`);}return box.innerHTML.replace('اشتراك واحد بـ١٩٩ ريال شهريًا.',`باقة ${p.name} بـ${p.price} ريال شهريًا.`).replace('بطاقات غير محدودة', 'عملاء غير محدودين');};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='choose-plan'){e.preventDefault();e.stopImmediatePropagation();requestedPlan=b.dataset.plan;whatsapp();}else if(b.dataset.action==='whatsapp'){requestedPlan=publicPage?'basic':RijaaPlans.forAccount(shopAccount()).id;}else if(b.dataset.action==='issue-token'){queueMicrotask(()=>{const period=document.querySelector('#token-period');if(period&&!document.querySelector('#token-plan'))period.closest('label').insertAdjacentHTML('afterend',`<label class="field"><span>باقة التوكن</span><select id="token-plan">${planOptions(RijaaPlans.forAccount(db.accounts.find(a=>a.id===b.dataset.id)).id)}</select></label>`);});}},true);
const planStyle=document.createElement('style');planStyle.textContent='.pricing{display:block}.plans-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:28px}.plans-grid .price-card{width:auto}.plans-grid .feature-list{margin:20px 0}.plans-grid .price{white-space:nowrap}@media(max-width:850px){.plans-grid{grid-template-columns:1fr}}';document.head.append(planStyle);
render();
